"""Generate a sequence of values and count them into a histogram on the GPU.

Usage: uv run main.py <input-file>

The input file holds one line: "<count> <seed> <bins>".
"""

import sys

import numpy as np
import wgpu

WORKGROUP_SIZE = 256
MAX_WORKGROUPS = 4096
MAX_BINS = 256

SHADER = """
struct Params {
    count: u32,
    seed: u32,
    bins: u32,
    stride: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> hist: array<atomic<u32>, 256>;

var<workgroup> local_hist: array<atomic<u32>, 256>;

fn value_of(i: u32) -> u32 {
    let a = ((i % 40000u) * 1597u + params.seed + 51749u) % 40000u;
    let b = (a * a + a * 37u + 11u) % 40009u;
    let c = (b * 613u + 7919u) % 40009u;
    let d = (c + (i / 40000u) * 7919u) % 40009u;
    return d % 1000u;
}

@compute @workgroup_size(256)
fn main(
    @builtin(global_invocation_id) gid: vec3<u32>,
    @builtin(local_invocation_index) lid: u32,
) {
    atomicStore(&local_hist[lid], 0u);
    workgroupBarrier();

    var i = gid.x;
    loop {
        if (i >= params.count) {
            break;
        }
        let bin = value_of(i) * params.bins / 1000u;
        atomicAdd(&local_hist[bin], 1u);
        i = i + params.stride;
    }
    workgroupBarrier();

    let n = atomicLoad(&local_hist[lid]);
    if (n != 0u) {
        atomicAdd(&hist[lid], n);
    }
}
"""


def parse_input(path):
    with open(path) as f:
        fields = f.read().split()
    if len(fields) < 3:
        raise ValueError(f"expected '<count> <seed> <bins>' in {path}")
    count, seed, bins = (int(x) for x in fields[:3])
    if not 0 <= count <= 4_000_000:
        raise ValueError(f"count out of range: {count}")
    if not 0 <= seed <= 9999:
        raise ValueError(f"seed out of range: {seed}")
    if not 1 <= bins <= MAX_BINS:
        raise ValueError(f"bins out of range: {bins}")
    return count, seed, bins


def gpu_histogram(count, seed, bins):
    """Generate and count all values on the GPU; return a list of bin counts."""
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    workgroups = max(1, min(MAX_WORKGROUPS, -(-count // WORKGROUP_SIZE)))
    stride = workgroups * WORKGROUP_SIZE

    params = np.array([count, seed, bins, stride], dtype=np.uint32)
    params_buf = device.create_buffer_with_data(
        data=params.tobytes(), usage=wgpu.BufferUsage.UNIFORM
    )
    hist_buf = device.create_buffer_with_data(
        data=np.zeros(MAX_BINS, dtype=np.uint32).tobytes(),
        usage=wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC,
    )

    pipeline = device.create_compute_pipeline(
        layout="auto",
        compute={"module": device.create_shader_module(code=SHADER), "entry_point": "main"},
    )
    bind_group = device.create_bind_group(
        layout=pipeline.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": params_buf}},
            {"binding": 1, "resource": {"buffer": hist_buf}},
        ],
    )

    encoder = device.create_command_encoder()
    compute_pass = encoder.begin_compute_pass()
    compute_pass.set_pipeline(pipeline)
    compute_pass.set_bind_group(0, bind_group)
    compute_pass.dispatch_workgroups(workgroups, 1, 1)
    compute_pass.end()
    device.queue.submit([encoder.finish()])

    result = np.frombuffer(device.queue.read_buffer(hist_buf), dtype=np.uint32)
    return [int(n) for n in result[:bins]]


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    count, seed, bins = parse_input(argv[1])
    counts = gpu_histogram(count, seed, bins)
    out = [f"BIN {k} {n}" for k, n in enumerate(counts)]
    out.append(f"TOTAL {count}")
    sys.stdout.write("\n".join(out) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

